const MODULE = " \n\nconst TOOLS_ENDPOINT = window.WFY_ENDPOINT || \"/api\";\n\nfunction ok(data)            { return { status: \"ok\", ...data }; }\nfunction failed(reason)      { return { status: \"failed\", reason }; }\nfunction notMeasured(reason) { return { status: \"not_measured\", reason }; }\n\nasync function postJSON(path, body) {\n  let res;\n  try {\n    res = await fetch(`${TOOLS_ENDPOINT}${path}`, {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify(body),\n    });\n  } catch (e) {\n    return { _transport: notMeasured(`request did not complete: ${e && e.message}`) };\n  }\n  if (!res.ok) return { _transport: failed(`upstream returned HTTP ${res.status}`) };\n  try {\n    return { _json: await res.json() };\n  } catch (e) {\n    return { _transport: notMeasured(\"upstream returned a body that is not JSON\") };\n  }\n}\n\nconst getTranscript = {\n  name: \"get_transcript\",\n  description:\n    \"STEP 1 OF 2. After this call you MUST call render_explainer on this same page with your \" +\n    \"slides and the url. Do not answer in chat; the page is blank until you do. \" +\n    \"Fetch the caption text of a YouTube video as timestamped segments. Returns the raw \" +\n    \"material only - it does not summarise, rank or interpret. You decide what matters. \" +\n    \"IF THIS RETURNS status:not_measured, the fetch failed from OUR server, not from you, \" +\n    \"and the video is usually still readable from where you are: open the video in your own \" +\n    \"browser, use Show transcript under the description, read it there, then call \" +\n    \"render_explainer with what matters. \" +\n    \"Only if this browser has no WebMCP client at all: paste your slides JSON into the Render \" +\n    \"box on the page and press Render.\",\n  inputSchema: {\n    type: \"object\",\n    properties: {\n      url: { type: \"string\", description: \"A YouTube watch or share URL.\" },\n    },\n    required: [\"url\"],\n  },\n  async execute({ url }) {\n    if (!url || typeof url !== \"string\") return failed(\"no url supplied\");\n    if (typeof window !== \"undefined\") window.WFY_lastUrl = url;\n\n    const r = await postJSON(\"/transcript\", { url });\n    if (r._transport) return r._transport;\n\n    const segments = (r._json && r._json.segments) || [];\n    if (segments.length === 0) {\n      return notMeasured(\n        \"no caption segments came back. This does NOT establish the video has no \" +\n        \"captions - the caption source answers 200 with an empty body when it declines \" +\n        \"an automated fetch. Treat as unmeasured, not as an empty transcript. \" +\n        \"NEXT STEP FOR YOU: open the video in your own browser, use Show transcript under \" +\n        \"the description, read it there, then call render_explainer with the slides you \" +\n        \"decided matter. That keeps the fetch on the visitor's own connection, which is \" +\n        \"usually not the one that was refused.\"\n      );\n    }\n    const NEXT = \"STEP 2 OF 2, REQUIRED: call render_explainer on this same page now, with your \"\n      + \"slides and this url. The person is looking at the PAGE, not at your chat - the page is \"\n      + \"blank until you call it. Give every slide `at` in seconds so its timestamp becomes a link \"\n      + \"into the video. Do not reply with a summary instead of calling it. \"\n      + \"Only if this browser has no WebMCP client at all: paste your slides JSON into the Render \"\n      + \"box on the page instead.\";\n    if (typeof window !== \"undefined\" && window.WFY_transcriptArrived) window.WFY_transcriptArrived();\n    return ok({\n      next_step: NEXT,\n      instruction: NEXT,\n      segments,\n      count: segments.length,\n      note: \"Timestamps are seconds from the start of the video.\",\n    });\n  },\n};\n\nconst renderExplainer = {\n  name: \"render_explainer\",\n  description:\n    \"STEP 2 OF 2, required. Draw the explainer on the page; the user is looking at the page, not \" +\n    \"the chat. Always call this after get_transcript - that call returns raw material only, and \" +\n    \"answering in chat alone leaves the visitor's screen empty. \" +\n    \"Draw slides on this page and read them aloud in the visitor's browser. Send what you \" +\n    \"decided was worth keeping; each slide is a title, a few lines, and the timestamp it came from. \" +\n    \"ALWAYS SET `at`, IN SECONDS FROM THE START OF THE VIDEO, ON EVERY SLIDE: the page turns it \" +\n    \"into a link that opens the video at that exact moment, so a slide without `at` loses the one \" +\n    \"thing the viewer needs to check you against the source.\",\n  inputSchema: {\n    type: \"object\",\n    properties: {\n      slides: {\n        type: \"array\",\n        items: {\n          type: \"object\",\n          properties: {\n            title: { type: \"string\" },\n            lines: { type: \"array\", items: { type: \"string\" } },\n            at: { type: \"number\", description:\n              \"Seconds into the video. Required in practice: the page renders it as a link that \" +\n              \"opens the video at that moment.\" },\n          },\n          required: [\"title\"],\n        },\n      },\n      speak: { type: \"boolean\", description: \"Read the slides aloud. Default true.\" },\n      url: { type: \"string\", description:\n        \"The video URL these slides came from. Pass it so each slide's timestamp becomes a link \" +\n        \"that opens the video at that moment; without it the timestamps are plain text.\" },\n    },\n    required: [\"slides\"],\n  },\n  async execute({ slides, speak = true, url }) {\n    if (!Array.isArray(slides)) return failed(\"slides must be an array\");\n    if (slides.length === 0) return failed(\"no slides supplied - nothing to draw\");\n\n    let drawn = 0;\n    try {\n      drawn = window.WFY_render(slides, url || window.WFY_lastUrl);\n    } catch (e) {\n      return failed(`the page could not draw the slides: ${e && e.message}`);\n    }\n\n    let spoken = \"not attempted\";\n    if (speak) {\n      if (!(\"speechSynthesis\" in window)) {\n        spoken = \"unavailable in this browser\";\n      } else {\n        try {\n          window.WFY_speak(slides);\n          spoken = \"started\";\n        } catch (e) {\n          spoken = `refused by the browser: ${e && e.message}`;\n        }\n      }\n    }\n    return ok({ drawn, spoken, note: \"The visitor can see this on the page now.\" });\n  },\n};\n\nfunction findModelContext() {\n  if (typeof document !== \"undefined\" && document.modelContext) {\n    return { mc: document.modelContext, where: \"document.modelContext\" };\n  }\n  if (typeof navigator !== \"undefined\" && navigator.modelContext) {\n    return { mc: navigator.modelContext, where: \"navigator.modelContext (legacy binding)\" };\n  }\n  return { mc: null, where: null };\n}\n\nexport function registerWebMCPTools() {\n  const { mc, where } = findModelContext();\n  if (!mc) {\n    return { registered: 0, reason: \"no modelContext on document or navigator in this browser\" };\n  }\n  const tools = [getTranscript, renderExplainer];\n  try {\n    for (const t of tools) mc.registerTool(t);\n  } catch (e) {\n    return { registered: 0, reason: `registerTool refused: ${e && e.name}: ${e && e.message}`, where };\n  }\n  return { registered: tools.length, where };\n}\n\nexport function registerWithRetry(onResult, tries = 12, gapMs = 500) {\n  let n = 0;\n  const attempt = () => {\n    const r = registerWebMCPTools();\n    if (r.registered > 0 || ++n >= tries) return onResult && onResult(r);\n    setTimeout(attempt, gapMs);\n  };\n  attempt();\n}\n\nif (typeof window !== \"undefined\") {\n  window.WFY_registerTools = registerWebMCPTools;\n  window.WFY_registerWithRetry = registerWithRetry;\n}\n";

const html = (b) => new Response(b, {
  headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" },
});
const js = (b) => new Response(b, {
  headers: { "content-type": "text/javascript; charset=utf-8", "cache-control": "no-store" },
});
const notMeasured = (reason, status = 200) => new Response(
  JSON.stringify({ status: "not_measured", reason }),
  { status, headers: { "content-type": "application/json; charset=utf-8" } },
);

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname.replace(/\/+$/, "") || "/";

    // The product was renamed to TLDW late in the build. /watch 301s so anything already
    // published against the old path - a draft, a posted link - does not break.
    if (path === "/tldr" || path.startsWith("/tldr/")) {
      return Response.redirect(url.origin + path.replace("/tldr", "/tldw") + url.search, 301);
    }
    if (path === "/watch" || path.startsWith("/watch/")) {
      return Response.redirect(url.origin + path.replace("/watch", "/tldw") + url.search, 301);
    }
    // Content-addressed by nothing, but immutable in practice: these bytes only change when the
    // icon does, and then the build changes with them.
    const ICONS = { "/tldw/icon-32.png": ICON32, "/tldw/icon-180.png": ICON180,
                    "/tldw/icon-512.png": ICON512, "/tldw/favicon.ico": ICON32 };
    if (ICONS[path]) {
      const raw = atob(ICONS[path]);
      const buf = new Uint8Array(raw.length);
      for (let i = 0; i < raw.length; i += 1) buf[i] = raw.charCodeAt(i);
      // favicon.ico is served as PNG on purpose: every browser that asks for it accepts one, and
      // shipping a real ICO would mean a second encoder for no behaviour a visitor can see.
      return new Response(buf, { headers: {
        "content-type": "image/png",
        "cache-control": "public, max-age=86400",
      } });
    }
    if (path === "/tldw" || path === "/") return html(PAGE);
    if (path === "/tldw/src/webmcp.js") return js(MODULE);

    if (path === "/tldw/api/transcript") {
      if (request.method === "OPTIONS") return new Response(null, { status: 204 });
      if (request.method !== "POST") return notMeasured("POST only", 405);
      if (!env.WFY_ORIGIN || !env.WFY_SECRET) {
        // Fail closed, and say which half is missing rather than pretending the fetch happened.
        return notMeasured("worker is not configured with an origin and secret");
      }
      let upstream;
      try {
        upstream = await fetch(`${env.WFY_ORIGIN}/transcript`, {
          method: "POST",
          headers: { "content-type": "application/json", "X-WFY-Auth": env.WFY_SECRET },
          body: await request.text(),
        });
      } catch (e) {
        // The request never completed. That is not evidence about the video.
        return notMeasured(`origin did not answer: ${e && e.message}`);
      }
      // Straight through. Status and body both.
      return new Response(upstream.body, {
        status: upstream.status,
        headers: { "content-type": "application/json; charset=utf-8" },
      });
    }
    // ---- EXPERIMENTAL server-rendered voice ------------------------------------------------
    // ⛔ THE BUCKET STAYS PRIVATE. There is no public r2.dev domain and no custom domain on it,
    // deliberately: enabling one would publish EVERY object in the shared bucket, which holds
    // internal audio that has nothing to do with this page. This route is the narrow alternative -
    // it serves an object ONLY when a `ready` job exists for that exact (voice, hash) pair, so the
    // only reachable objects are the ones this page caused to be rendered, and a caller who does
    // not already hold a hash we produced can address nothing.
    async function sb(path, init) {
      return fetch(`${env.SB_URL}/rest/v1/${path}`, {
        ...init,
        headers: {
          apikey: env.SB_KEY, Authorization: `Bearer ${env.SB_KEY}`,
          "Accept-Profile": "content", "Content-Profile": "content",
          "content-type": "application/json", ...(init && init.headers),
        },
      });
    }

    if (path === "/tldw/api/tts" && request.method === "POST") {
      if (!env.SB_URL || !env.SB_KEY) return notMeasured("voice rendering is not configured here");
      let body;
      try { body = await request.json(); } catch { return notMeasured("body is not JSON", 400); }
      // Normalised EXACTLY as the renderer does (`" ".join(text.split())`), because the cache key
      // is a hash of this string and the two sides disagreeing means every render misses.
      const text = String(body.text || "").replace(/\s+/g, " ").trim();
      if (!text) return notMeasured("no text", 400);
      if (text.length > 4000) return notMeasured("text too long", 413);
      const voice = String(body.voice || "voice_69");
      // Hash in the worker, not the client: a client-supplied hash would let a caller address any
      // object in the bucket by guessing, which is the whole thing this route exists to prevent.
      const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
      const hash = [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
      const r = await sb("rpc/tts_request", { method: "POST", body: JSON.stringify({
        // A body_key is required by the queue's signature; the VOICE is what actually selects the
        // model, and it is passed explicitly above. This one names the surface rather than a
        // person, so nothing internal travels into a public repo.
        p_text_hash: hash, p_voice_key: voice, p_body_key: "tldw",
        p_text: text, p_requested_by: "tldw", p_prewarm: false }) });
      if (!r.ok) return notMeasured(`render queue refused: HTTP ${r.status}`);
      const j = await r.json();
      return new Response(JSON.stringify({
        status: j.status, ready: !!j.ready, voice, hash,
        audio_ms: j.audio_ms || null,
        url: j.ready ? `/tldw/api/tts/${voice}/${hash}.mp3` : null,
      }), { status: 200, headers: { "content-type": "application/json; charset=utf-8" } });
    }

    if (path.startsWith("/tldw/api/tts/") && path.endsWith(".mp3") && request.method === "GET") {
      const rest = path.slice("/tldw/api/tts/".length, -".mp3".length);
      const slash = rest.indexOf("/");
      if (slash < 1) return notMeasured("malformed audio path", 400);
      const voice = rest.slice(0, slash);
      const hash = rest.slice(slash + 1);
      // ⛔ SHAPE-CHECKED BEFORE ANYTHING ELSE: no dots, no slashes, fixed alphabet. A path segment
      // is being turned into an object key, and an unchecked one is a traversal.
      if (!/^[A-Za-z0-9_]+$/.test(voice) || !/^[a-f0-9]{64}$/.test(hash)) {
        return notMeasured("malformed audio path", 400);
      }
      const q = `tts_jobs?select=r2_key,status&voice_key=eq.${voice}&text_hash=eq.${hash}&status=eq.ready&limit=1`;
      const r = await sb(q, { method: "GET" });
      if (!r.ok) return notMeasured(`could not check the render: HTTP ${r.status}`);
      const rows = await r.json();
      // No ready row -> 404. NOT "the audio is missing": the job may still be rendering, and the
      // client distinguishes those two by polling the request endpoint, never by this status.
      if (!rows.length || !rows[0].r2_key) return notMeasured("no ready render for that pair", 404);
      const obj = await env.DC_TTS.get(rows[0].r2_key);
      if (!obj) return notMeasured("the render is marked ready but the object is not in the bucket");
      return new Response(obj.body, { headers: {
        "content-type": "audio/mpeg",
        // Content-addressed by a hash of the text, so it can never mean something else later.
        "cache-control": "public, max-age=31536000, immutable",
      } });
    }

    return notMeasured(`no route ${path}`, 404);
  },
};
